<template>
  <div>
    <el-button size="small" class="mt-10" type="primary" @click="addUser"
      >新增</el-button
    >
    <el-table
      :data="tableData"
      style="width: 100%"
      class="mt-10"
      v-loading="loading"
    >
      <el-table-column type="index" label="序号" align="center" />
      <el-table-column prop="user_name" label="用户名" align="center" />
      <el-table-column label="操作" align="center">
        <template slot-scope="scope">
          <el-button
            type="text"
            @click="editUser(scope.row)"
            class="el-icon-edit"
          ></el-button>
          <el-button
            type="text"
            @click="delUser(scope.row)"
            class="el-icon-delete"
            style="color: red"
          ></el-button>
        </template>
      </el-table-column>
    </el-table>
    <el-pagination
      style="float: right"
      class="mt-20"
      background
      layout="prev, pager, next"
      :total="total"
      @current-change="handleCurrentChange"
      :current-page="page"
      :page-size="size"
    >
    </el-pagination>
    <el-dialog
      :title="visibleTitle"
      :visible.sync="addVisible"
      width="30%"
      :close-on-click-modal="false"
    >
      <el-form
        :model="ruleForm"
        :rules="rules"
        ref="ruleForm"
        label-width="100px"
        class="demo-ruleForm"
      >
        <el-form-item label="用户名" prop="user_name">
          <el-input v-model="ruleForm.user_name"></el-input>
        </el-form-item>
        <el-form-item label="密码" prop="user_pwd">
          <el-input v-model="ruleForm.user_pwd" type="password"></el-input>
        </el-form-item>
        <el-form-item label="确认密码" prop="aginPwd">
          <el-input v-model="ruleForm.aginPwd" type="password"></el-input>
        </el-form-item>
      </el-form>
      <span slot="footer" class="dialog-footer">
        <el-button @click="addVisible = false">取 消</el-button>
        <el-button type="primary" @click="submitForm('ruleForm')"
          >确 定</el-button
        >
      </span>
    </el-dialog>
  </div>
</template>

<script>
export default {
  data() {
    let validatePass = (rule, value, callback) => {
      if (value !== this.ruleForm.user_pwd) {
        callback(new Error("两次输入密码不一致!"));
      } else {
        callback();
      }
    };
    return {
      tableData: [],
      ruleForm: {},
      rules: {
        user_name: [
          { required: true, message: "请输入用户名", trigger: "blur" },
        ],
        user_pwd: [
          { required: true, message: "请输入密码", trigger: "change" },
        ],
        aginPwd: [
          { required: true, message: "请输入密码", trigger: "change" },
          { validator: validatePass, trigger: "change" },
        ],
      },
      addVisible: false,
      total: 0,
      page: 1,
      size: 10,
      visibleTitle: "新增",
      loading: false,
    };
  },
  created() {
    this.getUserList();
  },
  methods: {
    handleCurrentChange(e) {
      this.page = e;
      this.getUserList();
    },
    delUser(row) {
      this.$confirm("是否删除该用户?", "提示", {
        confirmButtonText: "确定",
        cancelButtonText: "取消",
        type: "warning",
      })
        .then(() => {
          this.$api
            .post("/user/delUser", {
              id: row.id,
            })
            .then(() => {
              this.$message.success("操作成功");
              this.getUserList();
            });
        })
        .catch(() => {
          this.$message({
            type: "info",
            message: "已取消删除",
          });
        });
    },
    editUser(row) {
      this.ruleForm = {
        user_name: row.user_name,
        id: row.id,
      };
      this.visibleTitle = "编辑";
      this.addVisible = true;
    },
    submitForm(formName) {
      this.$refs[formName].validate((valid) => {
        if (valid) {
          delete this.ruleForm.aginPwd;
          if (this.ruleForm.id) {
            this.$api.post("/user/updateUser", this.ruleForm).then(() => {
              this.$message.success("操作成功");
              this.addVisible = false;
              this.getUserList();
            });
          } else {
            this.$api.post("/user/addUser", this.ruleForm).then(() => {
              this.$message.success("操作成功");
              this.addVisible = false;
              this.getUserList();
            });
          }
        } else {
          return false;
        }
      });
    },
    addUser() {
      this.ruleForm = {};
      this.visibleTitle = "新增";
      this.addVisible = true;
    },
    getUserList() {
      this.loading = true;
      this.$api
        .get(`/user/userList?page=${this.page}&size=${this.size}`)
        .then((res) => {
          this.tableData = res.data.data;
          this.total = res.data.total;
        })
        .finally(() => {
          this.loading = false;
        });
    },
  },
};
</script>

